import java.util.Arrays; public final class LoanReceipt {private final String member;private final String[]books;public LoanReceipt(String m,String[]b){member=m;books=Arrays.copyOf(b,b.length);}public String[]getBookIds(){return Arrays.copyOf(books,books.length);}public LoanReceipt withBookIds(String[]b){return new LoanReceipt(member,b);}public static void main(String[]a){System.out.println(new LoanReceipt("M1",new String[]{"B1"}).getBookIds()[0]);}}
